// World billboards projected through one retreating camera. Screen units at final framing.
import {depotEase} from './depot-motion.js?v=depot-v17';
const lerp=(a,b,t)=>a+(b-a)*t;
export function depotCamera(age,f){const start=f.depotCameraStart??8,end=f.depotCameraEnd??30,t=Math.max(0,Math.min(1,(age-start)/Math.max(.1,end-start)));const retreat=f.depotCameraEase==='linear'?t:f.depotCameraEase==='smooth'?depotEase(t):t*(2-t);const drop=depotEase((age-start)/4),settle=depotEase((age-start-5)/Math.max(1,end-start-5));return {x:lerp(f.depotCameraStartX??500,480,retreat),y:lerp(lerp(f.depotCameraStartY??260,f.depotCameraLowY??310,drop),270,settle),z:(f.depotCameraDistance??1200)*(1-retreat),horizon:270,retreat,age}}
export function projectDepotObject(o,camera){const z=o.worldZ??({back:2900,mid:2300,near:1800,people:1000,front:650}[o.depth]??1000),distance=z-camera.z,strength=o.depthStrength??1;if(strength===0)return {visible:true,x:o.x,y:o.y,scale:1,rotation:o.rotation||0,z};if(distance<40)return {visible:false,x:0,y:0,scale:0,z};const scale=1+(z/distance-1)*strength,px=480+((o.x-480)*z-(camera.x-480)*1000)/distance,py=camera.horizon+((o.y-camera.horizon)*z-(camera.y-camera.horizon)*1000)/distance;return {visible:true,x:o.x+(px-o.x)*strength,y:o.y+(py-o.y)*strength,scale,rotation:o.rotation||0,z}}
export function framePoint(x,y,s,f,zOffset=0){const yaw=(f.depotFrameTilt??35)*s.tilt*Math.PI/180,roll=s.angle,X=x*Math.cos(yaw)+zOffset*Math.sin(yaw),Z=-x*Math.sin(yaw)+zOffset*Math.cos(yaw),perspective=1800/(1800+Z),px=X*s.scale*perspective,py=y*s.scale*perspective;return {x:480+px*Math.cos(roll)-py*Math.sin(roll),y:270+px*Math.sin(roll)+py*Math.cos(roll)}}
export function drawPerspectiveFrame(ctx,image,s,f){const W=image.width,H=image.height,nx=16,ny=10;const at=(u,v)=>framePoint(u-W/2,v-H/2,s,f);function tri(src,dst){ctx.save();const center={x:(dst[0].x+dst[1].x+dst[2].x)/3,y:(dst[0].y+dst[1].y+dst[2].y)/3},clip=dst.map(p=>{const dx=p.x-center.x,dy=p.y-center.y,l=Math.hypot(dx,dy)||1;return {x:p.x+dx/l*.8,y:p.y+dy/l*.8}});ctx.beginPath();ctx.moveTo(clip[0].x,clip[0].y);ctx.lineTo(clip[1].x,clip[1].y);ctx.lineTo(clip[2].x,clip[2].y);ctx.closePath();ctx.clip();const [a,b,c]=src,[A,B,C]=dst,den=a.x*(b.y-c.y)+b.x*(c.y-a.y)+c.x*(a.y-b.y);if(Math.abs(den)>1e-8){const ax=(A.x*(b.y-c.y)+B.x*(c.y-a.y)+C.x*(a.y-b.y))/den,bx=(A.y*(b.y-c.y)+B.y*(c.y-a.y)+C.y*(a.y-b.y))/den,cx=(A.x*(c.x-b.x)+B.x*(a.x-c.x)+C.x*(b.x-a.x))/den,dx=(A.y*(c.x-b.x)+B.y*(a.x-c.x)+C.y*(b.x-a.x))/den,ex=(A.x*(b.x*c.y-c.x*b.y)+B.x*(c.x*a.y-a.x*c.y)+C.x*(a.x*b.y-b.x*a.y))/den,fx=(A.y*(b.x*c.y-c.x*b.y)+B.y*(c.x*a.y-a.x*c.y)+C.y*(a.x*b.y-b.x*a.y))/den;ctx.transform(ax,bx,cx,dx,ex,fx);ctx.drawImage(image,0,0)}ctx.restore()}for(let y=0;y<ny;y++)for(let x=0;x<nx;x++){const u=x*W/nx,v=y*H/ny,U=(x+1)*W/nx,V=(y+1)*H/ny,a={x:u,y:v},b={x:U,y:v},c={x:U,y:V},d={x:u,y:V};tri([a,b,c],[at(u,v),at(U,v),at(U,V)]);tri([a,c,d],[at(u,v),at(U,V),at(u,V)])}}

// Slice projection gives cargo/figures editable yaw and pitch without baking them into assets.
export function drawDepotSurface(c,image,o){const yaw=(o.yaw||0)*Math.PI/180,pitch=(o.pitch||0)*Math.PI/180,W=o.width,H=o.height;if(Math.abs(yaw)+Math.abs(pitch)<.001){c.drawImage(image,-W/2,-H/2,W,H);return}const n=24,focal=Math.max(W,H)*2.5;for(let i=0;i<n;i++){const x=(i/n-.5)*W,X=x*Math.cos(yaw),z=-x*Math.sin(yaw),perspective=focal/(focal+z),next=((i+1)/n-.5)*W,p2=focal/(focal-next*Math.sin(yaw)),left=X*perspective,right=next*Math.cos(yaw)*p2,y=x*Math.sin(pitch)*.2;c.drawImage(image,i*image.width/n,0,image.width/n,image.height,left,y-H*Math.cos(pitch)*perspective/2,right-left+.6,H*Math.cos(pitch)*perspective)}}
